            return ADCS_E_RANGE;
        }

        if (!isfinite(wheels[i].inertia_kg_m2) || wheels[i].inertia_kg_m2 <= 0.0) {
            h->x = 0.0; h->y = 0.0; h->z = 0.0;
            return ADCS_E_RANGE;
        }

        if (!isfinite(wheels[i].speed_rad_s)) {
            h->x = 0.0; h->y = 0.0; h->z = 0.0;
            return ADCS_E_RANGE;
        }
    }

    for (size_t i = 0; i < count; i++) {
        adcs_vec3_t norm_axis;
        adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &norm_axis);

        double mag = wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s;
        adcs_vec3_t term = adcs_vec3_scale(&norm_axis, mag);

        h->x += term.x;
        h->y += term.y;
        h->z += term.z;
    }

    return ADCS_OK;
}

