candidates.raw:
    if ((wheels == NULL) || (momentum_body_nms == NULL)) {
        return ADCS_E_NULL;
    }

    if ((count < 1) || (count > 16)) {
        *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    size_t i;
    // Step 1: Validate all wheels completely before any accumulation
    for (i = 0; i < count; i++) {
        // Check axis_body is finite
        if (!adcs_is_finite_vec3(&wheels[i].axis_body)) {
            *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
        // Check inertia is finite and positive
        if (!isfinite(wheels[i].inertia_kg_m2) || (wheels[i].inertia_kg_m2 <= 0.0)) {
            *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
        // Check speed is finite
        if (!isfinite(wheels[i].speed_rad_s)) {
            *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
    }

    // Step 2: Accumulate in index order
    adcs_vec3_t total_h = {0.0, 0.0, 0.0};
    adcs_vec3_t axis_norm;

    for (i = 0; i < count; i++) {
        // Normalize the body-axis direction. 
        // Although we checked finiteness, we must ensure the vector is not zero/near-zero.
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis_norm) != ADCS_OK) {
            // Invalid axis (e.g., zero length)
            *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }

        // h_k = J_k * omega_k * a_k
        double scalar = wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s;
        adcs_vec3_t h_k = adcs_vec3_scale(&axis_norm, scalar);

        // Total momentum is vector sum
        total_h = adcs_vec3_add(&total_h, &h_k);
    }

    *momentum_body_nms = total_h;
    return ADCS_OK;
}

